import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    aim=0.0
    if cam:
        a=math.radians(obs['rig']['trailer_heading_deg'])
        left=[]; right=[]
        for b,d in cam.get('walls',[]):
            q=math.radians(b)-a
            s=-d*math.cos(q); y=d*math.sin(q)
            if 2.5<s<5.5:
                (left if y>0 else right).append((s,y))
        if left and right:
            ly=sum(y for s,y in left)/len(left)
            ry=sum(y for s,y in right)/len(right)
            dist=(sum(s for s,y in left)/len(left)+sum(s for s,y in right)/len(right))/2
            aim=max(-32,min(32,math.degrees(math.atan2(5.2*(ly+ry)/2,dist*dist))))
    steer=max(-34,min(34,2.2*(h-aim)+0.72*h))
    return (steer,-0.8,-23)

