distance=0.0
done=False
def control(obs):
    global distance,done
    distance+=max(0,-obs['motion']['v_mps'])*obs['dt']
    h=obs['hitch_deg']
    desired=-32.0
    feed=math.degrees(math.atan(1.25*math.sin(math.radians(desired))/(0.85+0.3*math.cos(math.radians(desired)))))
    steer=max(-45,min(45,feed+4*(h-desired)))
    if distance>=0.65:
        if not done:
            done=True
            wake('Check alley alignment and clearance')
        return (steer,0,-130)
    return (steer,-0.16,-130)

